  private peek(): Token {
    return this.tokens[this.i];
  }

  private next(): Token {
    return this.tokens[this.i++];
  }

  private expectOp(op: string): void {
    const t = this.next();
    if (t.kind !== 'op' || t.op !== op) throw new SyntaxError(`expected ${op}`, t.pos);
